static bool z_t81_endsWith(const z_t81_t* self, const z_t81_t* suffix) {
    if (suffix->size > self->size) return false;
    if (suffix->size == 0) return true;
    return memcmp(self->data + (self->size - suffix->size),
                  suffix->data, suffix->size) == 0;
}

static uint64_t z_t81_indexOf_raw(const z_t81_t* self, const z_t81_t* needle);
static uint64_t z_t81_indexOf_raw(const z_t81_t* self, const z_t81_t* needle) {
    if (needle->size == 0) return 0;
    if (needle->size > self->size) return UINT64_MAX;
    uint64_t last = self->size - needle->size;
    for (uint64_t i = 0; i <= last; i++) {
        if (memcmp(self->data + i, needle->data, needle->size) == 0) {
            return i;
        }
    }
    return UINT64_MAX;
}


static bool z_t81_contains(const z_t81_t* self, const z_t81_t* needle);
static bool z_t81_contains(const z_t81_t* self, const z_t81_t* needle) {
    return z_t81_indexOf_raw(self, needle) != UINT64_MAX;
}

static bool z_ascii_is_ws(unsigned char c);
static bool z_ascii_is_ws(unsigned char c) {
    return c == ' ' || c == '\t' || c == '\n'
        || c == '\v' || c == '\f' || c == '\r';
}

static z_t81_t z_t81_substring(const z_t81_t* self, uint64_t from, uint64_t to);
static z_t81_t z_t81_substring(const z_t81_t* self, uint64_t from, uint64_t to) {
    if (from > self->size || to > self->size || from > to) z_panic("substring: bounds error");
    return (z_t81_t){ .size = to - from, .data = self->data + from };
}
static uint64_t z_t81_hash(const z_t81_t* self);
static uint64_t z_t81_hash(const z_t81_t* self) {
    return z_siphash_stringview(*self);
}
static uint64_t z_t81_fastHash(const z_t81_t* self);
static uint64_t z_t81_fastHash(const z_t81_t* self) {
    return z_fasthash_stringview(*self);
}
static z_t81_t z_t81_trim(const z_t81_t* self);
static z_t81_t z_t81_trim(const z_t81_t* self) {
    const char* p = self->data;
    const char* end = self->data + self->size;
    while (p < end && z_ascii_is_ws((unsigned char)*p)) p++;
    while (end > p && z_ascii_is_ws((unsigned char)end[-1])) end--;
    z_t81_t out = { .size = (uint64_t)(end - p), .data = p };
    return out;
}

static z_t61_t z_t81_replace_impl(
    const z_t81_t* self, const z_t81_t* needle,
    const z_t81_t* repl, bool once);
static z_t61_t z_t81_replace_impl(
    const z_t81_t* self, const z_t81_t* needle,
    const z_t81_t* repl, bool once) {
    /* empty needle: just copy self */
    if (needle->size == 0) {
        z_t61_t z = {0};
        z.size = self->size;
        z.capacity = self->size + 1;
        z.data = (char*)z_xmalloc(z.capacity + 1);
        memcpy(z.data, self->data, self->size);
        z.data[self->size] = '\0';
        return z;
    }
    /* pass 1: count matches so we can size the output once */
    uint64_t matches = 0;
    if (needle->size <= self->size) {
        uint64_t last = self->size - needle->size;
        uint64_t i = 0;
        while (i <= last) {
            if (memcmp(self->data + i, needle->data, needle->size) == 0) {
                matches++;
                i += needle->size;
                if (once) break;
            } else {
                i++;
            }
        }
    }
    uint64_t delta_per =
        (repl->size > needle->size)
            ? (repl->size - needle->size)
            : 0;
    uint64_t shrink_per =
        (needle->size > repl->size)
            ? (needle->size - repl->size)
            : 0;
    uint64_t out_len = self->size + matches * delta_per - matches * shrink_per;
    z_t61_t z = {0};
    z.size = out_len;
    z.capacity = out_len + 1;
    z.data = (char*)z_xmalloc(z.capacity + 1);
    /* pass 2: copy with replacement */
    uint64_t src_i = 0, dst_i = 0, done_matches = 0;
    while (src_i < self->size) {
        bool can_match = (done_matches < matches)
                      && (src_i + needle->size <= self->size)
                      && (memcmp(self->data + src_i, needle->data, needle->size) == 0);
        if (can_match) {
            memcpy(z.data + dst_i, repl->data, repl->size);
            dst_i += repl->size;
            src_i += needle->size;
            done_matches++;
        } else {
            z.data[dst_i++] = self->data[src_i++];
        }
    }
    z.data[dst_i] = '\0';
    return z;
}

static z_t61_t z_t81_replace(
    const z_t81_t* self, const z_t81_t* needle,
    const z_t81_t* replacement);
static z_t61_t z_t81_replace(
    const z_t81_t* self, const z_t81_t* needle,
    const z_t81_t* replacement) {
    return z_t81_replace_impl(self, needle, replacement, false);
}

static z_t61_t z_t81_concat(
    const z_t81_t* self, const z_t81_t* other);
static z_t61_t z_t81_concat(
    const z_t81_t* self, const z_t81_t* other) {
    z_t61_t z = {0};
    uint64_t total = self->size + other->size;
    z.size = total;
    z.capacity = total + 1;
    z.data = (char*)z_xmalloc(z.capacity + 1);
    memcpy(z.data, self->data, self->size);
    memcpy(z.data + self->size, other->data, other->size);
    z.data[total] = '\0';
    return z;
}

static z_t2739_t z_t81_indexOf(const z_t81_t* self, const z_t81_t* needle);
static z_t2739_t z_t81_indexOf(const z_t81_t* self, const z_t81_t* needle) {
    z_t2739_t out = {0};
    uint64_t r = z_t81_indexOf_raw(self, needle);
    if (r == UINT64_MAX) {
        out.tag = Z_T2739_TAG_0;
        return out;
    }
    out.tag = Z_T2739_TAG_1;
    out.data.a1 = r;
    return out;
}


static z_t2739_t z_t81_lastIndexOf(const z_t81_t* self, const z_t81_t* needle);
static z_t2739_t z_t81_lastIndexOf(const z_t81_t* self, const z_t81_t* needle) {
    z_t2739_t out = {0};
    if (needle->size == 0) {
        out.tag = Z_T2739_TAG_1;
        out.data.a1 = self->size;
        return out;
    }
    if (needle->size > self->size) {
        out.tag = Z_T2739_TAG_0;
        return out;
    }
    for (uint64_t i = self->size - needle->size + 1; i > 0; i--) {
        uint64_t idx = i - 1;
        if (memcmp(self->data + idx, needle->data, needle->size) == 0) {
            out.tag = Z_T2739_TAG_1;
            out.data.a1 = idx;
            return out;
        }
    }
    out.tag = Z_T2739_TAG_0;
    return out;
}


static z_t1836_t z_t81_byteAt(const z_t81_t* self, uint64_t i);
